html:
{%- set accent = "#e8262d" -%}
{%- set wordmark = frappe.utils.get_url("/files/kilo-wordmark-trimmed.png") -%}
{%- set badge = frappe.utils.get_url("/files/kilo-badge-trimmed.png") -%}
{%- set license_no = frappe.db.get_value("Customer", doc.customer, "custom_license_number") -%}
{%- set rep = frappe.db.get_value("User", doc.owner, "full_name") -%}
<style>
    .kq * { box-sizing: border-box; }
    .kq {
        font-family: Helvetica, Arial, sans-serif;
        color: #111;
        font-size: 12.5px;
        line-height: 1.45;
        padding: 8px 4px;
    }
    .kq .kq-caps {
        font-family: "Arial Narrow", "Helvetica Neue Condensed", Impact, Helvetica, sans-serif;
        text-transform: uppercase;
        letter-spacing: 2px;
        font-weight: bold;
    }
    .kq-header { width: 100%; border-collapse: collapse; }
    .kq-header td { vertical-align: top; border: none !important; padding: 0; background: #fff !important; }
    .kq-rule {
        border: none;
        border-top: 3px solid {{ accent }};
        margin: 14px 0 18px;
    }
    .kq-doctitle {
        font-family: "Arial Narrow", Impact, Helvetica, sans-serif;
        font-size: 52px;
        font-weight: bold;
        text-transform: uppercase;
        letter-spacing: 1px;
        line-height: 1;
        margin: 0 0 14px;
    }
    .kq-top { width: 100%; }
    .kq-top > tbody > tr > td { vertical-align: top; border: none; padding: 0; }
    .kq-co-name { font-size: 19px; font-weight: bold; margin: 0; }
    .kq-co-sub { font-size: 14px; font-weight: bold; margin: 0 0 8px; }
    .kq-co-line { margin: 0; font-size: 13px; }
    .kq-meta { width: 100%; border-collapse: collapse; }
    .kq-meta td {
        border: none;
        border-bottom: 1.5px solid #111;
        padding: 6px 2px;
        font-size: 12.5px;
    }
    .kq-meta .kq-caps { letter-spacing: 1.5px; font-size: 12px; }
    .kq-party-title {
        color: {{ accent }};
        font-size: 13px;
        letter-spacing: 2px;
        margin: 0 0 8px;
    }
    .kq-party-name { font-weight: bold; font-size: 14px; margin: 0 0 4px; }
    .kq-party p { margin: 0 0 3px; }
    .kq-items { width: 100%; border-collapse: collapse; margin-top: 28px; }
    .kq-items th {
        text-align: left;
        font-size: 11px;
        letter-spacing: 1.5px;
        border: none !important;
        border-top: 2px solid #111 !important;
        border-bottom: 2px solid #111 !important;
        padding: 8px 6px;
        background: #fff !important;
        color: #111 !important;
    }
    .kq-items td {
        border: none;
        border-bottom: 1px solid #d9d9d9;
        padding: 9px 6px;
        font-size: 12.5px;
    }
    .kq-items .kq-item-name { font-weight: bold; font-size: 13px; }
    .kq-items .kq-item-desc { color: #333; font-size: 12px; }
    .kq-num { text-align: right; white-space: nowrap; }
    .kq-center { text-align: center; white-space: nowrap; }
    .kq-bottom { width: 100%; margin-top: 26px; }
    .kq-bottom > tbody > tr > td { vertical-align: top; border: none; padding: 0; }
    .kq-notes-title { color: {{ accent }}; font-size: 13px; letter-spacing: 2px; margin: 0 0 8px; }
    .kq-notes ul { margin: 0; padding-left: 18px; }
    .kq-notes li { margin-bottom: 6px; font-size: 12px; }
    .kq-totals { width: 100%; border-collapse: collapse; }
    .kq-totals td { border: none; padding: 7px 4px; font-size: 13px; }
    .kq-totals tr { border-bottom: 1px solid #111; }
    .kq-totals .kq-caps { letter-spacing: 1.5px; font-size: 12px; }
    .kq-totals .kq-discount { color: {{ accent }}; }
    .kq-grand td {
        border-top: 3px solid #111;
        padding-top: 12px;
        font-family: "Arial Narrow", Impact, Helvetica, sans-serif;
        font-weight: bold;
    }
    .kq-grand .kq-grand-label { font-size: 22px; text-transform: uppercase; letter-spacing: 1px; }
    .kq-grand .kq-grand-value { font-size: 26px; color: {{ accent }}; text-align: right; }
    .kq-sign { width: 100%; margin-top: 56px; }
    .kq-sign td { border: none; padding: 0 30px 0 0; }
    .kq-sign .kq-sign-line { border-top: 2px solid #111; padding-top: 6px; font-size: 12px; }
</style>

<div class="kq">
    <table class="kq-header">
        <tr>
            <td style="width: 68%; text-align: left; vertical-align: top;">
                <img src="{{ wordmark }}" alt="Kilo &amp; Co."
                    style="width: 300px !important; max-width: 300px !important; height: auto !important; display: inline-block; margin: 0;">
            </td>
            <td style="width: 32%; text-align: right; vertical-align: top;">
                <img src="{{ badge }}" alt="K&amp;CO"
                    style="width: 100px !important; max-width: 100px !important; height: auto !important; display: inline-block; margin: 0;">
            </td>
        </tr>
    </table>

    <hr class="kq-rule">

    <table class="kq-top">
        <tr>
            <td style="width: 55%;">
                <h1 class="kq-doctitle">Sales Order</h1>
                <p class="kq-co-name">Kilo &amp; Co.</p>
                <p class="kq-co-sub">Premium Cannabis Supply</p>
                <p class="kq-co-line">douglas@kiloandco.com</p>
                <p class="kq-co-line">626-506-9415</p>
                <p class="kq-co-line">kiloandco.com</p>
            </td>
            <td style="width: 45%;">
                <table class="kq-meta">
                    <tr>
                        <td class="kq-caps">Order #:</td>
                        <td>{{ doc.name }}</td>
                    </tr>
                    <tr>
                        <td class="kq-caps">Date:</td>
                        <td>{{ frappe.utils.formatdate(doc.transaction_date, "MMM dd, yyyy") }}</td>
                    </tr>
                    {%- if doc.delivery_date %}
                    <tr>
                        <td class="kq-caps">Delivery Date:</td>
                        <td>{{ frappe.utils.formatdate(doc.delivery_date, "MMM dd, yyyy") }}</td>
                    </tr>
                    {%- endif %}
                    {%- if doc.payment_terms_template %}
                    <tr>
                        <td class="kq-caps">Terms:</td>
                        <td>{{ doc.payment_terms_template }}</td>
                    </tr>
                    {%- endif %}
                    <tr>
                        <td class="kq-caps">Sales Rep:</td>
                        <td>{{ rep or "" }}</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <div class="kq-party" style="margin-top: 26px;">
        <p class="kq-party-title kq-caps">Bill To:</p>
        <p class="kq-party-name">{{ doc.customer_name or doc.customer }}</p>
        {%- if license_no %}
        <p>License #: &nbsp;{{ license_no }}</p>
        {%- endif %}
    </div>

    <table class="kq-items">
        <thead>
            <tr>
                <th class="kq-caps" style="width: 20%;">Item</th>
                <th class="kq-caps" style="width: 38%;">Item Group</th>
                <th class="kq-caps kq-center" style="width: 12%;">Qty</th>
                <th class="kq-caps kq-num" style="width: 15%;">Unit Price</th>
                <th class="kq-caps kq-num" style="width: 15%;">Line Total</th>
            </tr>
        </thead>
        <tbody>
            {%- for row in doc.items %}
            <tr>
                <td class="kq-item-name">{{ row.item_name or row.item_code }}</td>
                <td class="kq-item-desc">{{ frappe.db.get_value("Item", row.item_code, "item_group") or "" }}</td>
                <td class="kq-center">{{ frappe.utils.fmt_money(row.qty, 2).replace(".00", "") }}{{ row.uom | lower if row.uom else "" }}</td>
                <td class="kq-num">{{ row.get_formatted("rate") }}</td>
                <td class="kq-num">{{ row.get_formatted("amount") }}</td>
            </tr>
            {%- endfor %}
        </tbody>
    </table>

    <table class="kq-bottom">
        <tr>
            <td class="kq-notes" style="width: 52%; padding-right: 30px;">
                <p class="kq-notes-title kq-caps">Notes &amp; Terms</p>
                {%- if doc.terms %}
                <div>{{ doc.terms }}</div>
                {%- else %}
                <ul>
                    <li>Pricing subject to current availability and volume.</li>
                    <li>All products intended for licensed operators only.</li>
                    <li>COAs and compliance documentation available upon request.</li>
                    <li>Shipping charges are estimates and may vary.</li>
                    <li>Thank you for your business.</li>
                </ul>
                {%- endif %}
            </td>
            <td style="width: 48%;">
                <table class="kq-totals">
                    <tr>
                        <td class="kq-caps">Subtotal</td>
                        <td class="kq-num">{{ doc.get_formatted("total") }}</td>
                    </tr>
                    {%- if doc.discount_amount %}
                    <tr>
                        <td class="kq-caps kq-discount">
                            Discount{% if doc.additional_discount_percentage %} ({{ frappe.utils.fmt_money(doc.additional_discount_percentage, 2).replace(".00", "") }}%){% endif %}
                        </td>
                        <td class="kq-num kq-discount">-{{ doc.get_formatted("discount_amount") }}</td>
                    </tr>
                    {%- endif %}
                    {%- for tax in doc.taxes %}
                    {%- if tax.base_tax_amount_after_discount_amount %}
                    <tr>
                        <td class="kq-caps">{{ tax.description }}</td>
                        <td class="kq-num">{{ tax.get_formatted("base_tax_amount_after_discount_amount") }}</td>
                    </tr>
                    {%- endif %}
                    {%- endfor %}
                    <tr class="kq-grand">
                        <td class="kq-grand-label">Grand Total</td>
                        <td class="kq-grand-value">{{ doc.get_formatted("grand_total") }}</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <table class="kq-sign">
        <tr>
            <td style="width: 50%;"><div class="kq-sign-line">Approved By</div></td>
            <td style="width: 50%;"><div class="kq-sign-line">Date</div></td>
        </tr>
    </table>
</div>
